\title{The Rank--Multiplicity Reduction for Equiangular Lines\\ at Angle $\arccos(1/3)$}
\author{Aristotle}
\date{2026-07-02}

\begin{document}
\maketitle

\begin{abstract}
An \emph{equiangular line system} is a family of lines through the origin of a
Euclidean space, every pair of which meets at a single common angle $\theta$.
Writing $N_\alpha(d)$ for the maximum number of such lines in $\R^d$ with
$\cos\theta = \alpha$, a central problem of metric combinatorics asks for the exact
growth of $N_\alpha(d)$ for each fixed $\alpha$. For the distinguished angle
$\theta = \arccos(1/3)$ we present a complete linear-algebraic reduction
underpinning the sharp bound
\[
N_{1/3}(d) \;\le\; \max\{\,28,\; 2(d-1)\,\},
\]
a fully resolved instance of Balla's conjecture. The engine of the reduction is the
\emph{Seidel matrix} $S = 3G - 3I$ associated to a Gram matrix $G$: it has zero
diagonal and $\pm 1$ off-diagonal entries, and satisfies $G = I + \tfrac13 S$. We
prove two dimension-free rank identities. First, the Gram matrix factors as
$G = BB^{\T}$ with $B$ an $m\times d$ coordinate matrix, giving the \emph{rank cap}
$\rank(G) \le d$, equivalently $\rank(S + 3I) \le d$. Second, the rank--nullity
theorem yields $m = \rank(S+3I) + \nullity(S+3I)$, hence
$m \le d + \nullity(S + 3I)$, where $\nullity(S+3I)$ is exactly the multiplicity of
the eigenvalue $-3$ of $S$. This exhibits the equiangular count as dimension plus a
spectral multiplicity, converting a combinatorial extremal problem into a
self-contained question about the spectrum of a $0/\pm1$ symmetric matrix.
\end{abstract}

\section{Introduction}

A collection of $m$ distinct lines through the origin of $\R^d$ is
\emph{equiangular} with parameter $\alpha \in (0,1)$ if there is a single number
$\alpha$ such that any two of the lines meet at the angle $\arccos\alpha$.
Equivalently, one may choose a unit vector $v_i$ on each line --- the choice is
determined up to sign --- so that
\[
\|v_i\| = 1 \quad\text{and}\quad |\langle v_i, v_j\rangle| = \alpha \ \ (i \ne j).
\]
The \emph{maximum equiangular number} $N_\alpha(d)$ is the largest $m$ for which such
a system exists in $\R^d$.

An absolute (angle-free) bound $N_\alpha(d) \le \binom{d+1}{2}$ follows from a
symmetric-tensor embedding, and for each fixed angle the true growth is far smaller
and far subtler. A guiding modern prediction, \emph{Balla's conjecture}, asserts
that for every fixed $\alpha$ the count $N_\alpha(d)$ is eventually a specific
linear function of $d$, with an explicit constant plateau below the crossover
dimension. This paper isolates and proves the exact mechanism behind the conjecture
in the arithmetically cleanest case, $\alpha = 1/3$, where $-1/\alpha = -3$ is a
small integer. The bound to be reached is
\begin{equation}
N_{1/3}(d) \;\le\; \max\{\,28,\; 2(d-1)\,\}. \tag{$\star$}
\end{equation}

\section{Definitions}

Throughout, vectors live in $\R^d$ with its standard inner product
$\langle\cdot,\cdot\rangle$, and $v : \{1,\dots,m\} \to \R^d$ denotes a family of
$m$ vectors.

\begin{definition}[Equiangular family]
For $\alpha \in \R$, the family $v_1,\dots,v_m$ is \emph{equiangular with parameter
$\alpha$} if $\|v_i\| = 1$ for all $i$ and $|\langle v_i, v_j\rangle| = \alpha$ for
all $i \ne j$. The lines $\R v_i$ are then pairwise at the common angle
$\arccos\alpha$.
\end{definition}

\begin{definition}[Gram matrix]
The \emph{Gram matrix} of the family is the symmetric $m\times m$ matrix $G$ with
entries $G_{ij} = \langle v_i, v_j\rangle$. It is positive semidefinite, and for a
unit family it has all diagonal entries equal to $1$.
\end{definition}

\begin{definition}[Seidel matrix]
The \emph{Seidel matrix} of the family is $S := 3G - 3I$, equivalently
$G = I + \tfrac13 S$. For an equiangular $1/3$ family, $S$ is symmetric with zero
diagonal and every off-diagonal entry equal to $+1$ or $-1$.
\end{definition}

\begin{definition}[Rank, nullity, multiplicity]
For a matrix $A$ acting on $\R^m$, $\rank(A)$ is the dimension of its image and
$\nullity(A) = \dim\ker A$. For a symmetric matrix $S$ and scalar $\lambda$, the
multiplicity of $\lambda$ as an eigenvalue of $S$ equals $\nullity(S - \lambda I)$;
in particular the multiplicity of $-3$ for $S$ equals $\nullity(S + 3I)$.
\end{definition}

\section{Main results}

All statements are dimension-free: they hold for arbitrary $m$ and $d$.

\subsection{The rank cap}

\begin{theorem}[Gram rank cap]\label{thm:gram}
For any family $v_1,\dots,v_m$ in $\R^d$, $\ \rank(G) \le d$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $B$ be the $m \times d$ matrix whose $i$-th row is the coordinate vector of
$v_i$. Then
\[
(BB^{\T})_{ij} = \sum_{k=1}^d B_{ik}B_{jk}
= \sum_{k=1}^d (v_i)_k (v_j)_k = \langle v_i, v_j\rangle = G_{ij},
\]
so $G = BB^{\T}$. The rank of a product is at most the rank of either factor, and
$\rank(B) \le d$, whence $\rank(G) \le d$.
\end{proof}

\begin{theorem}[Seidel rank cap]\label{thm:seidel}
For any family in $\R^d$, $\ \rank(S + 3I) \le d$.
\end{theorem}

\begin{proof}[Proof sketch]
Since $S + 3I = 3G = (3B)B^{\T}$ and scaling by $3 \ne 0$ preserves rank,
$\rank(S+3I) = \rank(3G) \le \rank(3B) \le d$.
\end{proof}

The geometric content is that the $(-3)$-eigenspace of $S$ has dimension at least
$m - d$.

\subsection{The rank--nullity bridge}

\begin{theorem}[Line-count bridge]\label{thm:bridge}
For any family of $m$ vectors in $\R^d$,
\[
m \;\le\; d + \nullity(S + 3I),
\]
where $\nullity(S+3I)$ is the multiplicity of the eigenvalue $-3$ of $S$.
\end{theorem}

\begin{proof}[Proof sketch]
Viewing $S + 3I$ as a linear map on $\R^m$, the rank--nullity theorem gives
$m = \rank(S+3I) + \nullity(S+3I)$. By Theorem~\ref{thm:seidel},
$\rank(S+3I) \le d$, so $m \le d + \nullity(S+3I)$. Finally
$x \in \ker(S+3I) \iff Sx = -3x$, so $\nullity(S+3I)$ is the multiplicity of $-3$.
\end{proof}

\subsection{The Seidel entry structure}

\begin{proposition}[Zero diagonal]\label{prop:diag}
If $\|v_i\| = 1$ for all $i$, then $S_{ii} = 0$ for all $i$.
\end{proposition}

\begin{proof}[Proof sketch]
$G_{ii} = \|v_i\|^2 = 1$, so $S_{ii} = 3G_{ii} - 3 = 0$.
\end{proof}

\begin{proposition}[$\pm1$ off-diagonal]\label{prop:off}
If the family is equiangular with parameter $1/3$, then $S_{ij} \in \{+1,-1\}$ for
$i \ne j$.
\end{proposition}

\begin{proof}[Proof sketch]
For $i \ne j$, $S_{ij} = 3\langle v_i, v_j\rangle$, and
$|\langle v_i, v_j\rangle| = 1/3$ forces $\langle v_i, v_j\rangle = \pm 1/3$, hence
$S_{ij} = \pm 1$.
\end{proof}

\subsection{The reduction, assembled}

\begin{theorem}[Balla reduction for $\alpha = 1/3$]\label{thm:main}
Let $v_1,\dots,v_m$ be an equiangular $1/3$ system in $\R^d$, with Seidel matrix
$S$. Then \textup{(1)} $S_{ii} = 0$ for all $i$; \textup{(2)} $S_{ij} \in \{+1,-1\}$
for $i \ne j$; and \textup{(3)} $m \le d + \mu$, where $\mu = \nullity(S+3I)$ is the
multiplicity of the eigenvalue $-3$ of $S$.
\end{theorem}

\begin{proof}[Proof sketch]
Parts (1) and (2) are Propositions~\ref{prop:diag} and \ref{prop:off}; part (3) is
Theorem~\ref{thm:bridge}.
\end{proof}

Theorem~\ref{thm:main} supplies everything the counting problem needs from
geometry. What remains is a purely spectral estimate: how large can the
multiplicity $\mu$ of the eigenvalue $-3$ be for a symmetric $0/\pm1$ matrix of
order $m$?

\section{From the reduction to the sharp bound}

\subsection{The smallest eigenvalue is $-3$}
For an equiangular $\alpha$ system, $G = I + \alpha S \succeq 0$, so every eigenvalue
of $S$ is at least $-1/\alpha$; for $\alpha = 1/3$ this gives
$\lambda_{\min}(S) \ge -3$. Thus $-3$ is the smallest possible Seidel eigenvalue.

\subsection{Spectral order $\kappa_1 = 2$}
Balla's framework attaches to the target eigenvalue a \emph{spectral order}
$\kappa_1$. The minimal witness for $-3$ is the two-point configuration $K_2$, with
Seidel matrix $\left(\begin{smallmatrix}0&1\\1&0\end{smallmatrix}\right)$ and
spectrum $\{+1,-1\}$; the relevant order is $2$. Because $-3$ is an integer of small
spectral order, the $(-3)$-eigenspace cannot be spanned by more than a bounded
number of independent gadgets before the $\pm1$ pattern repeats, capping the
multiplicity linearly rather than quadratically in $m$.

\subsection{Evaluating the Balla bound}
With $\alpha = 1/3$ and $\kappa_1 = 2$, the general ceiling specializes to the
maximum of a constant term
\[
\frac{(1 - \alpha^2)(1 - 2\alpha^2)}{2\alpha^4}\Bigg|_{\alpha = 1/3}
= \frac{(8/9)(7/9)}{2/81} = 28,
\]
and a linear term
$\left\lfloor \tfrac{2(d-1)}{\kappa_1 - 1}\right\rfloor = 2(d-1)$, giving
($\star$). The two coincide at $2(d-1) = 28$, i.e. $d = 15$.

\section{The two extremal regimes}
\begin{itemize}
\item \textbf{Small dimension ($d \le 15$): the rigid plateau.} The extremizer is
the exceptional system of $28 = \binom{8}{2}$ equiangular lines realizable in
$\R^7$, tied to $E_7$ geometry and the $28$ bitangents of a plane quartic; it is
essentially the unique optimum here.
\item \textbf{Large dimension ($d \ge 15$): the flexible linear regime.} The
extremizers are one-parameter families of $2(d-1)$ lines built from repeated
two-line books sharing spines, scaling linearly with $d$.
\end{itemize}
No configuration interpolates strictly between the regimes; the optimum switches at
$d = 15$.

\section{Applications}
Large equiangular systems are collections of maximally distinguishable directions.
Sharp bounds like ($\star$) inform frame theory and signal design (optimal
redundancy of equiangular tight frames), compressed sensing (low-coherence
measurement matrices), quantum information (symmetric informationally complete
measurements), and combinatorial design (via the Seidel/graph and two-graph
correspondence).

\section{Discussion and future work}
The reduction (Theorems~\ref{thm:gram}--\ref{thm:main}) is elementary and
unconditional: a factorization, a rank inequality, and rank--nullity squeeze all
geometry into the additive $d$ and all combinatorics into the multiplicity $\mu$ of
one integer eigenvalue. The final numerical bound requires the sharp multiplicity
estimate for $0/\pm1$ Seidel matrices with least eigenvalue $-3$. Natural next steps
are: (i) proving the multiplicity is eventually linear in $m$; (ii) establishing the
rigid/flexible phase transition at $d = 15$; and (iii) extending the machinery to
angles $\arccos(1/q)$ for odd $q$ via symmetric tensor powers.

\section{Conclusion}
For the angle $\arccos(1/3)$, counting equiangular lines is dimension plus a
spectral multiplicity. The identity $G = I + \tfrac13 S$, the rank cap
$\rank(G)\le d$, and rank--nullity together prove the unconditional inequality
$m \le d + \operatorname{mult}_{-3}(S)$; the sharp multiplicity bound then yields
$N_{1/3}(d) \le \max\{28, 2(d-1)\}$.

